    db.put({.sync = true}, to_bytes("k4"), to_bytes("v4"));
    db.put({.sync = true}, to_bytes("k5"), to_bytes("v5"));
    // A range tombstone has to survive it too — recovery reads
    // it back out of the regenerated hint to suppress the range.
